/**
 * @fileoverview AI service types for Nanobanna Pro
 *
 * This file contains TypeScript type definitions for AI-related functionality including:
 * - Model metadata and provider configuration (ModelMetadata, ModelSelectionCache)
 * - Performance tracking and metrics (PerformanceMetric, MetricsSummary)
 * - Tool chaining and multi-step operations (ToolChain, ChainStep)
 * - Brand profile for consistency across generations (BrandProfile - app state version)
 * - Image editing sessions and history (ImageEditTurn, EditSession)
 * - Replicate API operations (ReplicateOperation)
 * - AI context for React state management (AIContextType)
 *
 * @see {@link ./database.ts} for BrandProfile database schema version
 * @see {@link ../services/llm.ts} for AI service implementations
 * @see {@link ../context/AIContext.tsx} for React context usage
 */

/**
 * Metadata describing an AI model's capabilities, performance, and cost characteristics.
 *
 * This type is used by the model router to make intelligent model selection decisions
 * based on the requested operation, quality preference, cost limits, and performance requirements.
 *
 * @example
 * ```typescript
 * const gpt5: ModelMetadata = {
 *   id: 'openai/gpt-5.1',
 *   provider: 'openrouter',
 *   name: 'GPT-5.1',
 *   capabilities: ['text', 'vision', 'thinking'],
 *   costPerCall: 0.015,
 *   avgResponseTime: 2500,
 *   qualityScore: 0.95,
 *   contextWindow: 128000
 * };
 * ```
 *
 * @see {@link ../services/modelRouter.ts} for model selection logic
 * @see {@link ../constants.ts} MODELS constant for available model definitions
 * @see {@link ModelSelectionCache} for user model preferences
 * @see {@link AIContextType.availableModels} for React context usage
 */
export interface ModelMetadata {
  /** Unique identifier for the model (e.g., 'gemini-3-pro-image-preview', 'openai/gpt-5.1') */
  id: string;
  /** AI service provider hosting this model */
  provider: 'gemini' | 'openrouter' | 'replicate';
  /** Human-readable display name for the model */
  name: string;
  /** Array of operations this model can perform (determines model routing eligibility) */
  capabilities: (
    | 'text'
    | 'vision'
    | 'thinking'
    | 'image_gen'
    | 'image_edit'
    | 'image_upscale'
    | 'background_removal'
    | 'image_restoration'
    | 'face_enhancement'
  )[];
  /** Estimated cost per API call in USD (used for cost-based model selection) */
  costPerCall: number;
  /** Average response time in milliseconds (used for speed-based model selection) */
  avgResponseTime: number;
  /** Quality score from 0-1 where 1 is highest quality (used for quality-based model selection) */
  qualityScore: number;
  /** Maximum context window size in tokens (optional, only for text/vision models) */
  contextWindow?: number;
}

export interface PerformanceMetric {
  id: string;
  modelId: string;
  provider: 'gemini' | 'openrouter' | 'replicate';
  operation:
    | 'text_gen'
    | 'image_gen'
    | 'image_edit'
    | 'upscale'
    | 'removebg'
    | 'inpaint'
    | 'outpaint'
    | 'restore'
    | 'faceenhance';
  timestamp: number;
  responseTime: number; // ms
  tokenUsage?: { input: number; output: number };
  cost: number; // USD
  success: boolean;
  errorMessage?: string;
}

export interface ToolChain {
  id: string;
  name?: string;
  steps: ChainStep[];
  currentStep: number;
  status: 'pending' | 'running' | 'completed' | 'failed';
  startedAt?: number;
  completedAt?: number;
}

export interface ChainStep {
  id: string;
  tool:
    | 'generate'
    | 'upscale'
    | 'edit'
    | 'removebg'
    | 'inpaint'
    | 'outpaint'
    | 'restore'
    | 'faceenhance';
  params: Record<string, string | number | boolean>;
  status: 'pending' | 'running' | 'completed' | 'failed';
  result?: string; // image URL or base64
  error?: string;
  startedAt?: number;
  completedAt?: number;
}

/**
 * Brand profile for app state (ephemeral, in-memory representation).
 *
 * ⚠️ IMPORTANT: This is the APP STATE version of BrandProfile used for React state management
 * and AI generation. There is also a DATABASE version in `database.ts` with different fields.
 *
 * **Key Differences from Database Version:**
 * - Uses camelCase (e.g., `logoUrl`, `styleKeywords`) instead of snake_case
 * - No database identifiers (`id`, `user_id`, `name`, `is_active`)
 * - No database timestamps (`created_at`, `updated_at`)
 * - Uses `lastUpdated: number` (Unix timestamp) for in-memory tracking
 * - `fonts` array is REQUIRED here (optional in database)
 *
 * **Data Flow:**
 * ```
 * Database (BrandProfile) → Load → Transform → App State (BrandProfile)
 *                                              ↓
 *                                         User edits
 *                                              ↓
 *                                    Transform → Save → Database
 * ```
 *
 * **When to Use:**
 * - AIContext state management
 * - Passing to AI generation services
 * - React component props
 * - In-memory brand consistency checks
 *
 * **When NOT to Use:**
 * - Database operations (use `database.ts` version instead)
 * - API request/response payloads to backend
 * - Supabase queries
 *
 * @example
 * ```typescript
 * // Loading from database
 * const dbProfile: BrandProfile = await database.getBrandProfile(userId);
 * const appProfile: BrandProfile = {
 *   colors: dbProfile.colors,
 *   fonts: dbProfile.fonts || [],
 *   styleKeywords: dbProfile.style_keywords || [],
 *   logoUrl: dbProfile.logo_url,
 *   industry: dbProfile.industry,
 *   targetAudience: dbProfile.target_audience,
 *   lastUpdated: Date.now(),
 *   version: dbProfile.version
 * };
 * ```
 *
 * @see {@link ../types/database.ts} BrandProfile for database schema version
 * @see {@link ../context/AIContext.tsx} for React state usage
 * @see {@link ../services/brandEngine.ts} for persistence logic
 */
export interface BrandProfile {
  /** Brand color palette with semantic usage tags */
  colors: { hex: string; name: string; usage: 'primary' | 'accent' | 'background' }[];
  /** Typography choices with semantic usage (heading/body) - REQUIRED in app state */
  fonts: { name: string; usage: 'heading' | 'body' }[];
  /** Style descriptors for AI generation (e.g., ["modern", "minimalist", "tech"]) */
  styleKeywords: string[];
  /** URL to brand logo image (optional) */
  logoUrl?: string;
  /** Industry/sector for context (e.g., "SaaS", "Finance", "E-commerce") */
  industry?: string;
  /** Target audience description (e.g., "B2B decision makers", "Gen Z consumers") */
  targetAudience?: string;
  /** Unix timestamp of last modification (for in-memory staleness tracking) */
  lastUpdated: number;
  /** Schema version number for future migrations */
  version: number;
}

export interface ImageEditTurn {
  id: string;
  prompt: string;
  inputImage: string; // base64
  outputImage: string; // base64
  timestamp: number;
  referenceImages?: string[];
  model?: string;
}

export interface ReplicateOperation {
  id: string;
  type: 'upscale' | 'removebg' | 'inpaint' | 'outpaint' | 'restore' | 'faceenhance';
  status: 'starting' | 'processing' | 'succeeded' | 'failed';
  progress: number; // 0-100
  predictionId?: string;
  inputImage?: string;
  outputImage?: string;
  error?: string;
}

export interface ModelSelectionCache {
  autoSelectEnabled: boolean;
  manualOverride: string | null;
  preferredProvider: 'gemini' | 'openrouter' | 'replicate';
  qualityPreference: 'fast' | 'balanced' | 'best';
  costLimit: number; // Max $ per operation
  recentModels: string[]; // Last 5 used models
}

export interface EditSession {
  id: string;
  startedAt: number;
  baseImage: string;
  turns: ImageEditTurn[];
  currentImage: string;
  referenceImages: string[];
}

export interface MetricsSummary {
  totalCalls: number;
  totalCost: number;
  avgResponseTime: number;
  successRate: number;
  byModel: Record<string, { calls: number; cost: number; avgTime: number }>;
  lastUpdated: number;
}

/**
 * React context interface for AI-related state management.
 *
 * This interface defines the complete API surface for the AIContext, which manages:
 * - Model selection and routing across providers (Gemini, OpenRouter, Replicate)
 * - Performance metrics and cost tracking across all AI operations
 * - Multi-step tool chaining for complex AI workflows
 * - Brand profile consistency across generations
 * - Image editing history and session management
 * - Replicate API operation status tracking
 *
 * **Architecture:**
 * AIContext sits between the UI layer and AI services, providing:
 * - Centralized state for AI configuration (model selection, brand profile)
 * - Performance monitoring and cost control
 * - Workflow orchestration (tool chains, edit sessions)
 * - Real-time operation status (Replicate operations)
 *
 * **Usage Pattern:**
 * ```typescript
 * // In a component
 * const { selectedModel, brandProfile, addMetric } = useAI();
 *
 * // Use model selection
 * console.log('Current model:', selectedModel);
 *
 * // Track performance
 * addMetric({
 *   id: nanoid(),
 *   modelId: selectedModel,
 *   provider: 'gemini',
 *   operation: 'image_gen',
 *   timestamp: Date.now(),
 *   responseTime: 2500,
 *   cost: 0.015,
 *   success: true
 * });
 * ```
 *
 * **State Categories:**
 * 1. **Model Selection**: Provider, model, overrides, available models
 * 2. **Performance Tracking**: Metrics collection, cost/time aggregation
 * 3. **Tool Chaining**: Multi-step workflow management
 * 4. **Brand Consistency**: Brand profile state (app version, not database)
 * 5. **Edit History**: Multi-turn image editing sessions
 * 6. **Replicate Status**: Real-time operation tracking
 *
 * @example
 * ```typescript
 * // Provided by AIContext.tsx
 * <AIProvider>
 *   <YourComponent />
 * </AIProvider>
 *
 * // Consumed via useAI hook
 * import { useAI } from '@/context/AIContext';
 * const ai = useAI();
 * ```
 *
 * @see {@link ../context/AIContext.tsx} for React context implementation
 * @see {@link ../services/modelRouter.ts} for model selection logic
 * @see {@link ModelMetadata} for available model definitions
 * @see {@link BrandProfile} for brand profile structure (app state version)
 */
export interface AIContextType {
  // Model Selection
  /** Currently selected AI provider (gemini, openrouter, or replicate) */
  selectedProvider: 'gemini' | 'openrouter' | 'replicate';
  /** Update the selected provider (triggers model list update) */
  setSelectedProvider: (provider: 'gemini' | 'openrouter' | 'replicate') => void;
  /** Currently selected model ID (e.g., 'gemini-3-pro-image-preview') */
  selectedModel: string;
  /** Update the selected model */
  setSelectedModel: (model: string) => void;
  /** Array of all available models across all providers with metadata */
  availableModels: ModelMetadata[];
  /** Manual model override (bypasses auto-selection, null = use auto-selection) */
  modelOverride: string | null;
  /** Set manual model override (null to enable auto-selection) */
  setModelOverride: (model: string | null) => void;

  // Performance Tracking
  /** Array of all performance metrics recorded during this session */
  performanceMetrics: PerformanceMetric[];
  /** Add a new performance metric for tracking */
  addMetric: (metric: PerformanceMetric) => void;
  /** Calculate total cost across all operations in USD */
  getTotalCost: () => number;
  /** Calculate average response time across all operations in ms */
  getAvgResponseTime: () => number;

  // Tool Chaining
  /** Currently active multi-step tool chain (null if none) */
  activeChain: ToolChain | null;
  /** Set or clear the active tool chain */
  setActiveChain: (chain: ToolChain | null) => void;
  /** Progress percentage (0-100) of current chain execution */
  chainProgress: number;

  // Brand Consistency
  /** Current brand profile for consistent AI generations (app state version, null if not set) */
  brandProfile: BrandProfile | null;
  /** Update brand profile (partial update supported) */
  updateBrandProfile: (profile: Partial<BrandProfile>) => void;

  // Multi-turn Image Editing
  /** History of all image editing turns in the current session */
  editHistory: ImageEditTurn[];
  /** Add a new editing turn to history */
  addEditTurn: (turn: ImageEditTurn) => void;
  /** Clear all editing history (reset session) */
  clearEditHistory: () => void;

  // Replicate Operations
  /** Currently running Replicate operation status (null if none) */
  replicateOperation: ReplicateOperation | null;
  /** Set or update Replicate operation status (supports functional updates) */
  setReplicateOperation: (
    op:
      | ReplicateOperation
      | null
      | ((prev: ReplicateOperation | null) => ReplicateOperation | null),
  ) => void;
}
